#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU,
# including SKUs whose movements cancel out to zero. SKU-9 is in the catalog
# and must appear even when it has no movements.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     END {
         for (sku in seen) print sku, net[sku];
         print "SKU-9", 0
     }' movements.log | sort -u > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log, including SKUs whose movements cancel out to
# zero. Catalog SKU-9 must appear even when it has no movements that day.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     END {
         for (sku in seen) print sku, net[sku];
         if (!("SKU-9" in seen)) print "SKU-9", 0
     }' movements.log | sort -u > stock.txt
